  document.getElementById("sidebar").innerHTML=`<div class="sidebar-brand">Sitcom<span>English in Action</span></div><div class="sidebar-primary">${sidebarHtml}<button class="nav-button" type="button" onclick="openSearch()"><span class="nav-icon">${lineIcon("search")}</span><span>Search</span></button></div><div class="sidebar-secondary"><div class="sidebar-more"><button id="sidebarMoreButton" class="nav-button sidebar-more-button" type="button" aria-expanded="false" aria-controls="sidebarMoreMenu" onclick="toggleMoreMenu(event)"><span class="nav-icon">${lineIcon("settings")}</span><span>More</span></button><div id="sidebarMoreMenu" class="sidebar-more-panel" hidden>${soundSettingMarkup("sidebar-more-sound-setting")}<button class="sidebar-more-row" type="button" onclick="closeMoreMenu();openBackup()"><span class="drawer-icon">${lineIcon("backup")}</span><span>Backup</span></button><button class="sidebar-more-row" type="button" onclick="closeMoreMenu();openHelp()"><span class="drawer-icon">${lineIcon("help")}</span><span>Help</span></button><button class="sidebar-more-row" type="button" onclick="closeMoreMenu();openAbout()"><span class="drawer-icon">${lineIcon("info")}</span><span>About</span></button></div></div></div>`;
  const onHome=route.name==="home"&&!historyStack.length;
