function chips(values,selected,handler,prefix="",allLabel="ALL"){return `<div class="chips">${values.map(value=>{const active=String(value)===String(selected),label=value==="ALL"?allLabel:prefix==="E"?`E${String(value).padStart(2,"0")}`:`${prefix}${value}`;return `<button class="chip ${active?'selected':''}" aria-pressed="${active}" onclick="${handler}('${value}')">${esc(label)}</button>`}).join("")}</div>`}
function quizResultDate(result){return result.completedDate||localDate(new Date(result.completedAt))}
function quizStatsMarkup(){const stored=readJSON(STORE.history,[]),h=Array.isArray(stored)?stored:[],testResults=h.filter(result=>result&&typeof result==="object"&&result.quizMode!=="practice"),last=testResults.at(-1),bestCandidates=testResults.filter(result=>result.total===10&&(result.scope==="random"||!Object.prototype.hasOwnProperty.call(result,"scope"))),best=bestCandidates.length?[...bestCandidates].sort((a,b)=>(b.score/b.total)-(a.score/a.total)||b.score-a.score)[0]:null,today=h.filter(result=>result&&typeof result==="object"&&quizResultDate(result)===localDate()).reduce((sum,result)=>sum+Number(result.total||0),0);return `<div class="stats-row"><div class="stat-box"><span>Last score</span><strong>${last?`${last.score}/${last.total}`:'—'}</strong></div><div class="stat-box"><span>Best score</span><strong>${best?`${best.score}/${best.total}`:'—'}</strong></div><div class="stat-box"><span>Today</span><strong>${today} Qs</strong></div></div>`}

