function setQuizOption(key,value){filters[key]=value;saveAppState();renderQuizHome()}
function setQuizMode(mode){filters.quizMode=mode==="practice"?"practice":"test";saveAppState();renderQuizHome()}
function quizPool(season=filters.quizSeason,scope=filters.quizScope){return PHRASES.filter(p=>(season==="ALL"||seasonNum(p.episode)===Number(season))&&(scope!=="star3"||Number(p.priority)===3)&&(scope!=="bookmarked"||bookmarked("phrase",p.id))&&(scope!=="weak"||isWeak(p.id))&&(scope!=="unlearned"||!isLearned(p.id))&&(scope!=="learned"||isLearned(p.id)))}
const QUIZ_SESSION_VERSIONS=new Set([2,3]),QUIZ_MODES=new Set(["test","practice"]),QUIZ_SCOPES=new Set(["random","star3","weak","unlearned","learned","bookmarked","mistakes"]),QUIZ_QUESTION_TYPES=new Set(["mixed","mc","enmc","fill"]),QUIZ_ITEM_TYPES=new Set(["mc","enmc","fill"]);
function normalizeQuizScope(scope){return scope==="all"?"random":scope==="important"?"star3":scope==="saved"||scope==="bookmarks"?"bookmarked":scope}
function normalizeQuizQuestionType(type){return type==="tf"?"enmc":type}
function quizChoiceIds(phrase,field){const seen=new Set([normalize(PHRASES.find(item=>item.id===phrase.id)?.[field])]),candidates=PHRASES.filter(item=>{const value=normalize(item[field]);if(item.id===phrase.id||!value||seen.has(value))return false;seen.add(value);return true}),others=sampleValues(candidates,3);return shuffle([phrase.id,...others.map(item=>item.id)])}
function normalizeQuizQuestion(question){if(question?.type!=="tf")return question;const phrase=PHRASES.find(item=>item.id===question.id);return phrase?{id:question.id,type:"enmc",choices:quizChoiceIds(phrase,"meaning")}:question}
function validateQuizQuestion(question,phraseIds){if(!question||typeof question!=="object"||Array.isArray(question)||typeof question.id!=="string"||!phraseIds.has(question.id)||!QUIZ_ITEM_TYPES.has(question.type))return false;if(question.type==="mc"||question.type==="enmc")return Array.isArray(question.choices)&&question.choices.length===4&&new Set(question.choices).size===question.choices.length&&question.choices.includes(question.id)&&question.choices.every(id=>typeof id==="string"&&phraseIds.has(id));return true}
function validateQuizSession(session){if(!session||typeof session!=="object"||Array.isArray(session))return null;if(session.version!==undefined&&!QUIZ_SESSION_VERSIONS.has(session.version))return null;if(session.series!==undefined&&session.series!=="friends")return null;const quizMode=session.quizMode===undefined?"test":session.quizMode;if(!QUIZ_MODES.has(quizMode))return null;const season=session.season??"ALL";if(season!=="ALL"&&!SEASONS.includes(Number(season)))return null;const scope=normalizeQuizScope(session.scope??"random");if(!QUIZ_SCOPES.has(scope))return null;const questionType=normalizeQuizQuestionType(session.questionType??"mixed");if(!QUIZ_QUESTION_TYPES.has(questionType))return null;if(!Array.isArray(session.questions)||!session.questions.length||session.questions.length>15)return null;const questions=session.questions.map(normalizeQuizQuestion),phraseIds=new Set(PHRASES.map(phrase=>phrase.id));if(!questions.every(question=>validateQuizQuestion(question,phraseIds)))return null;if(!Number.isInteger(session.index)||session.index<0||session.index>=questions.length)return null;if(!Array.isArray(session.responses)||!Array.isArray(session.mistakes))return null;const responseIndexes=new Set();if(!session.responses.every(response=>response&&typeof response==="object"&&!Array.isArray(response)&&Number.isInteger(response.index)&&response.index>=0&&response.index<questions.length&&!responseIndexes.has(response.index)&&responseIndexes.add(response.index)&&typeof response.correct==="boolean"))return null;if(!session.mistakes.every(id=>typeof id==="string"&&phraseIds.has(id)))return null;if(!Number.isFinite(session.score)||session.score<0||session.score>questions.length)return null;const questionCount=session.questionCount??questions.length;if(!Number.isInteger(questionCount)||questionCount<1||questionCount>15)return null;for(const key of ["added","graduated"])if(session[key]!==undefined&&(!Number.isFinite(session[key])||session[key]<0))return null;return{...session,version:session.version??2,series:"friends",quizMode,season,scope,questionType,questionCount,questions,added:Number(session.added)||0,graduated:Number(session.graduated)||0}}
function getQuizSession({removeInvalid=true}={}){const raw=safeGetItem(STORE.quiz);if(raw===null)return null;let parsed;try{parsed=JSON.parse(raw)}catch{if(removeInvalid)safeRemoveItem(STORE.quiz);return null}const session=validateQuizSession(parsed);if(!session&&removeInvalid)safeRemoveItem(STORE.quiz);return session}
function returnToQuizHome(){safeRemoveItem(STORE.quiz);route={name:"quiz",params:{}};render()}
function renderQuizHome(){
  const session=getQuizSession(),practice=filters.quizMode==="practice",scope=practice?filters.quizScope:"random",pool=quizPool(filters.quizSeason,scope);
  const seasonGroup=`<div class="filter-group"><div class="filter-label">シーズン</div>${chips(["ALL",...SEASONS],filters.quizSeason,"setQuizOption.bind(null,'quizSeason')",'S','全て').replaceAll("setQuizOption.bind(null,'quizSeason')('","setQuizOption('quizSeason','")}</div>`;
  const scopeGroup=`<div class="filter-group"><div class="filter-label">絞り込み</div><div class="chips scope-chips"><button class="chip ${filters.quizScope==='random'?'selected':''}" onclick="setQuizOption('quizScope','random')">全て</button><button class="chip ${filters.quizScope==='star3'?'selected':''}" onclick="setQuizOption('quizScope','star3')">重要</button><button class="chip ${filters.quizScope==='weak'?'selected':''}" onclick="setQuizOption('quizScope','weak')">苦手</button><button class="chip ${filters.quizScope==='unlearned'?'selected':''}" onclick="setQuizOption('quizScope','unlearned')">未習得</button><button class="chip ${filters.quizScope==='learned'?'selected':''}" onclick="setQuizOption('quizScope','learned')">習得済み</button><button class="chip ${filters.quizScope==='bookmarked'?'selected':''}" onclick="setQuizOption('quizScope','bookmarked')">保存</button></div></div>`;
  const typeGroup=`<div class="filter-group"><div class="filter-label">問題形式</div><div class="chips quiz-setting-chips"><button class="chip ${filters.quizQuestionType==='mc'?'selected':''}" onclick="setQuizOption('quizQuestionType','mc')">日→英</button><button class="chip ${filters.quizQuestionType==='enmc'?'selected':''}" onclick="setQuizOption('quizQuestionType','enmc')">英→日</button><button class="chip ${filters.quizQuestionType==='fill'?'selected':''}" onclick="setQuizOption('quizQuestionType','fill')">入力</button></div></div>`;
  const countGroup=`<div class="filter-group"><div class="filter-label">問題数</div><div class="chips quiz-setting-chips">${[5,10,15].map(count=>`<button class="chip ${Number(filters.quizQuestionCount)===count?'selected':''}" onclick="setQuizOption('quizQuestionCount',${count})">${count}</button>`).join("")}</div></div>`;
  const startArea=session?`<div class="quiz-start-area"><div><strong>${session.quizMode==='practice'?'Practice':'Quiz'} in progress</strong><p class="page-subtitle">${session.responses.length} / ${session.questions.length} completed</p></div><div class="button-row"><button class="primary-button" onclick="resumeQuiz()">Resume Quiz</button><button class="secondary-button" onclick="confirmStartOver()">Start Over</button></div></div>`:`<div class="quiz-start-area">${!pool.length?'<div class="empty compact-empty quiz-empty" role="status">対象のフレーズがありません。</div>':''}<button class="primary-button quiz-start-button" ${pool.length?'onclick="startQuiz()"':'disabled'}>${practice?'Start Practice':'Start Quiz'}</button></div>`;
  const settings=practice?`${typeGroup}${countGroup}${scopeGroup}${seasonGroup}`:seasonGroup;
  const note=practice?`<div class="quiz-mode-note"><strong>練習モード</strong><span>形式・問題数を選べます。Best scoreには反映されません。</span></div>`:`<div class="quiz-mode-note"><strong>本番モード</strong><span>3形式Mix・10問。Best scoreに反映されます。</span></div>`;
  app.innerHTML=`${listPageHeader("Quiz")}<div class="segmented quiz-mode-tabs" role="tablist" aria-label="Quiz mode"><button class="seg-button ${!practice?'selected':''}" role="tab" aria-selected="${!practice}" onclick="setQuizMode('test')">本番</button><button class="seg-button ${practice?'selected':''}" role="tab" aria-selected="${practice}" onclick="setQuizMode('practice')">練習</button></div>${startArea}<section class="card filter-panel quiz-settings-panel">${settings}<div class="page-subtitle">${pool.length} phrases available</div></section>${practice?'':`<section class="card quiz-stats-card"><h2 class="section-title">Your Quiz</h2>${quizStatsMarkup()}</section>`}${note}`
}
function shuffle(values){return Array.from(values,value=>({value,order:Math.random()})).sort((a,b)=>a.order-b.order).map(item=>item.value)}
function sampleValues(values,count,predicate=()=>true){const sample=[];let seen=0;for(const value of values){if(!predicate(value))continue;seen++;if(sample.length<count)sample.push(value);else{const index=Math.floor(Math.random()*seen);if(index<count)sample[index]=value}}return shuffle(sample)}
function selectQuizPhrases(pool,count=10,avoidIds=[]){const unique=[...new Map(pool.map(phrase=>[phrase.id,phrase])).values()],avoid=new Set(avoidIds),limit=Math.min(Number(count)||10,unique.length),fresh=sampleValues(unique,limit,phrase=>!avoid.has(phrase.id)),previous=sampleValues(unique,limit-fresh.length,phrase=>avoid.has(phrase.id));return[...fresh,...previous]}
function createQuestions(pool,count=10,questionType="mixed",avoidIds=[]){const selected=selectQuizPhrases(pool,count,avoidIds),pattern=["mc","enmc","fill"],normalizedType=normalizeQuizQuestionType(questionType);return selected.map((p,i)=>{const type=normalizedType==="mixed"?pattern[i%pattern.length]:normalizedType;if(type==="mc"||type==="enmc")return{id:p.id,type,choices:quizChoiceIds(p,type==="enmc"?"meaning":"phrase")};return{id:p.id,type};})}
function beginQuizSession(session){const valid=validateQuizSession(session);if(!valid){safeRemoveItem(STORE.quiz);renderQuizHome();return false}writeJSON(STORE.quiz,valid);navigate("quizPlay");playQuizStartSound();return true}
function startQuiz(){const safeSettings=sanitizeSavedQuizFilters(filters),practice=safeSettings.quizMode==="practice",scope=practice?safeSettings.quizScope:"random",questionType=practice?safeSettings.quizQuestionType:"mixed",questionCount=practice?safeSettings.quizQuestionCount:10,pool=quizPool(safeSettings.quizSeason,scope);Object.assign(filters,safeSettings);if(!pool.length){renderQuizHome();return}const session={version:3,series:"friends",quizMode:practice?"practice":"test",season:safeSettings.quizSeason,scope,questionType,questionCount,questions:createQuestions(pool,questionCount,questionType),index:0,responses:[],score:0,added:0,graduated:0,mistakes:[],startedAt:new Date().toISOString()};beginQuizSession(session)}
function startQuickChallenge(){const pool=quizPool("ALL","random"),questionCount=Math.min(10,pool.length);if(!questionCount)return navigate("quiz");const session={version:3,series:"friends",quizMode:"test",season:"ALL",scope:"random",questionType:"mixed",questionCount,questions:createQuestions(pool,questionCount,"mixed"),index:0,responses:[],score:0,added:0,graduated:0,mistakes:[],startedAt:new Date().toISOString()};beginQuizSession(session)}
function resumeQuiz(){if(!getQuizSession())return renderQuizHome();navigate("quizPlay");playQuizStartSound()}
function confirmStartOver(){showConfirm("Start the quiz over? Your current quiz progress will be replaced.",()=>{safeRemoveItem(STORE.quiz);startQuiz()})}
function renderQuizPlay(){const s=getQuizSession();if(!s)return returnToQuizHome();const q=s.questions[s.index],p=q&&PHRASES.find(x=>x.id===q.id),choiceQuestion=q&&(q.type==="mc"||q.type==="enmc");if(!q||!p||(choiceQuestion&&(!Array.isArray(q.choices)||q.choices.some(id=>!PHRASES.some(phrase=>phrase.id===id)))))return returnToQuizHome();const response=s.responses.find(x=>x.index===s.index),progress=Math.round((s.responses.length/s.questions.length)*100);let question="",answers="";if(choiceQuestion){question=`<span class="quiz-prompt${q.type==='enmc'?' phrase-name':''}">${esc(q.type==="enmc"?p.phrase:p.meaning)}</span>`;answers=q.choices.map(id=>{const choice=PHRASES.find(x=>x.id===id),cls=response?(id===p.id?'correct':response.answer===id?'incorrect':''):'';return `<button class="answer-button ${cls}" ${response?'disabled':''} onclick="answerQuiz('${id}')">${esc(q.type==="enmc"?choice.meaning:choice.phrase)}</button>`}).join("")}else{question=`<span class="quiz-prompt">${esc(p.meaning)}</span>`;answers=response?`<input class="blank-input" value="${esc(response.answer)}" disabled><div class="example">Correct: ${esc(p.phrase)}</div>`:`<input id="fillAnswer" class="blank-input" autocomplete="off" placeholder="Type the phrase"><button class="primary-button" onclick="answerQuiz(document.getElementById('fillAnswer').value)">Check Answer</button>`}
  app.innerHTML=`<header class="quiz-play-header"><h1 class="quiz-question-count">Question ${s.index+1} / ${s.questions.length}</h1></header><div class="quiz-progress"><span style="width:${progress}%"></span></div><section class="card quiz-play-card"><div class="quiz-question">${question}</div><div class="answer-list">${answers}</div>${response?quizFeedback(p,response,s):""}</section>`;if(q.type==="fill"&&!response)setTimeout(()=>document.getElementById("fillAnswer")?.focus(),0)}
function answerQuiz(answer){const s=getQuizSession();if(!s||s.responses.some(x=>x.index===s.index))return;const q=s.questions[s.index],p=q&&PHRASES.find(x=>x.id===q.id);if(!q||!p)return returnToQuizHome();const correct=q.type==="fill"?typingAnswerMatches(answer,p.phrase):answer===p.id;let added=false,graduated=false;if(correct){graduated=markWeakCorrect(p.id)}else{added=markMiss(p.id);s.mistakes.push(p.id)}if(correct)s.score++;if(added)s.added++;if(graduated)s.graduated++;s.responses.push({index:s.index,answer,correct,added,graduated});writeJSON(STORE.quiz,s);playQuizSound(correct);renderQuizPlay()}
function quizFeedback(p,response,s){return `<div class="feedback ${response.correct?'good':'bad'}"><strong>${response.correct?'Correct':'Incorrect'}</strong><div>${esc(p.phrase)} — ${esc(p.meaning)}</div>${p.example1?`<div class="search-snippet">${esc(p.example1)}</div>`:""}</div><button class="primary-button" onclick="nextQuiz()">${s.index+1>=s.questions.length?'See Results':'Next Question'}</button>`}
function nextQuiz(){const s=getQuizSession();if(!s)return returnToQuizHome();if(s.index+1>=s.questions.length)return completeQuiz(s);s.index++;writeJSON(STORE.quiz,s);renderQuizPlay()}
function completeQuiz(s){const quizMode=s.quizMode==="practice"?"practice":"test",result={score:s.score,total:s.questions.length,mistakes:[...new Set(s.mistakes)],added:s.added,graduated:s.graduated,completedAt:new Date().toISOString(),completedDate:localDate(),scope:s.scope,quizMode},responses=new Map(s.responses.map(response=>[response.index,response])),items=s.questions.map((question,index)=>({id:question.id,correct:Boolean(responses.get(index)?.correct)})),nextRound={quizMode,season:s.season||"ALL",scope:s.scope||"random",questionType:s.questionType||"mixed",questionCount:Number(s.questionCount)||s.questions.length,poolIds:Array.isArray(s.poolIds)?[...s.poolIds]:null};const storedHistory=readJSON(STORE.history,[]),history=Array.isArray(storedHistory)?storedHistory:[];history.push(result);writeJSON(STORE.history,history.slice(-100));safeRemoveItem(STORE.quiz);route={name:"quizResult",params:{result:{...result,items,nextRound}}};render();playQuizCompleteSound(result.completedAt,result.score===result.total)}
function perfectConfettiMarkup(){return `<div class="perfect-confetti" aria-hidden="true">${Array.from({length:16},(_,index)=>`<i style="--confetti-left:${6+index*5.8}%;--confetti-delay:${index*18}ms;--confetti-drift:${(index-8)*8}px;--confetti-color:hsl(${index*47%360} 82% 67%)"></i>`).join("")}</div>`}
function showPerfectConfetti(){document.querySelectorAll("body>.perfect-confetti").forEach(element=>element.remove());const template=document.createElement("template");template.innerHTML=perfectConfettiMarkup();const overlay=template.content.firstElementChild;document.body.appendChild(overlay);requestAnimationFrame(()=>requestAnimationFrame(()=>overlay.classList.add("is-active")));setTimeout(()=>overlay.remove(),2200)}
function renderQuizResult(){const r=route.params.result||readJSON(STORE.history,[]).at(-1);if(!r)return navigate("quiz");const mistakes=r.mistakes.map(id=>PHRASES.find(x=>x.id===id)).filter(Boolean),items=(Array.isArray(r.items)?r.items:r.mistakes.map(id=>({id,correct:false}))).map(item=>({...item,phrase:PHRASES.find(x=>x.id===item.id)})).filter(item=>item.phrase),perfect=r.score===r.total,resultKey=String(r.completedAt||`${r.score}-${r.total}`),celebrate=perfect&&!celebratedQuizResults.has(resultKey);if(celebrate)celebratedQuizResults.add(resultKey);app.innerHTML=`<section class="card quiz-result-card"><div class="result-score">${r.score} / ${r.total}${perfect?' <span class="perfect-crown" role="img" aria-label="Perfect score">👑</span>':''}</div><div class="stats-row"><div class="stat-box"><span>Added to Weak</span><strong>${r.added}</strong></div><div class="stat-box"><span>Graduated</span><strong>${r.graduated}</strong></div><div class="stat-box"><span>Mistakes</span><strong>${mistakes.length}</strong></div></div><div class="quiz-result-actions section"><button class="primary-button" ${mistakes.length?'onclick="reviewMistakes()"':'disabled'}>Review mistakes</button><button class="primary-button" ${r.nextRound?'onclick="nextQuizRound()"':'disabled'}>Next Round</button><button class="primary-button" onclick="navTo('quiz')">Done</button></div>${items.length?`<div class="mistake-list quiz-result-list">${items.map((item,index)=>{const p=item.phrase,status=item.correct?'Correct':'Incorrect';return `<button class="learning-item mistake-item quiz-result-item" type="button" onclick="openPhrase('${p.id}')" aria-label="${index+1}. ${esc(p.phrase)}、${status}、詳細を開く"><span class="quiz-result-number" aria-hidden="true">${index+1}</span><span class="mistake-copy"><strong>${esc(p.phrase)}</strong><span>${esc(p.meaning)}</span></span><span class="quiz-result-status ${item.correct?'correct':'incorrect'}">${status}</span><span class="mistake-chevron" aria-hidden="true">›</span></button>`}).join("")}</div>`:""}</section>`;if(celebrate)showPerfectConfetti()}
function nextQuizRound(){const r=route.params.result,settings=r?.nextRound;if(!settings)return;const pool=settings.scope==="mistakes"?(settings.poolIds||[]).map(id=>PHRASES.find(phrase=>phrase.id===id)).filter(Boolean):quizPool(settings.season,settings.scope);if(!pool.length)return;const avoidIds=(r.items||[]).map(item=>item.id),questionCount=Math.min(Number(settings.questionCount)||10,pool.length),session={version:3,series:"friends",quizMode:settings.quizMode==="practice"?"practice":"test",season:settings.season||"ALL",scope:settings.scope||"random",questionType:settings.questionType||"mixed",questionCount,poolIds:settings.scope==="mistakes"?pool.map(phrase=>phrase.id):undefined,questions:createQuestions(pool,questionCount,settings.questionType||"mixed",avoidIds),index:0,responses:[],score:0,added:0,graduated:0,mistakes:[],startedAt:new Date().toISOString()};beginQuizSession(session)}
function reviewMistakes(){const r=route.params.result;if(!r?.mistakes?.length)return;const pool=r.mistakes.map(id=>PHRASES.find(p=>p.id===id)).filter(Boolean),questionCount=Math.min(10,pool.length),questionType=r.quizMode==="practice"?(r.nextRound?.questionType||"mixed"):"mixed";const s={version:3,series:"friends",quizMode:"practice",season:"ALL",scope:"mistakes",questionType,questionCount,poolIds:pool.map(phrase=>phrase.id),questions:createQuestions(pool,questionCount,questionType),index:0,responses:[],score:0,added:0,graduated:0,mistakes:[],startedAt:new Date().toISOString()};beginQuizSession(s)}

function normalizePhraseSearch(value){return String(value||"").toLowerCase().replace(/[’]/g,"'").replace(/（/g,"(").replace(/）/g,")").replace(/\s+/g," ").trim()}
const PHRASE_SEARCH_IRREGULAR_GROUPS=[
  ["go","goes","going","went","gone"],
  ["get","gets","getting","got","gotten"],
  ["take","takes","taking","took","taken"],
  ["make","makes","making","made"],
  ["come","comes","coming","came"],
  ["give","gives","giving","gave","given"],
  ["run","runs","running","ran"],
  ["see","sees","seeing","saw","seen"],
  ["know","knows","knowing","knew","known"],
  ["do","does","doing","did","done"],
  ["say","says","saying","said"],
  ["have","has","having","had"],
  ["be","am","is","are","was","were","been","being"]
];
const PHRASE_SEARCH_IRREGULAR_LOOKUP=new Map(PHRASE_SEARCH_IRREGULAR_GROUPS.flatMap(group=>group.map(form=>[form,new Set(group)])));
const PHRASE_SEARCH_ALIASES=new Map([["got",new Set(["gotta"])]]);
function phraseSearchTokens(value){return normalizePhraseSearch(value).match(/[a-z0-9]+(?:'[a-z0-9]+)*/g)||[]}
function phraseSearchRegularForms(base){if(!/^[a-z]{3,}$/.test(base))return new Set([base]);const forms=new Set([base]);if(/[^aeiou]y$/.test(base)){forms.add(`${base.slice(0,-1)}ies`);forms.add(`${base.slice(0,-1)}ied`)}else{forms.add(/(?:s|x|z|ch|sh|o)$/.test(base)?`${base}es`:`${base}s`);forms.add(base.endsWith("e")?`${base}d`:`${base}ed`)}if(base.endsWith("ie"))forms.add(`${base.slice(0,-2)}ying`);else if(base.endsWith("e")&&!/(?:ee|ye|oe)$/.test(base))forms.add(`${base.slice(0,-1)}ing`);else forms.add(`${base}ing`);if(/[aeiou][^aeiouwxy]$/.test(base)){forms.add(`${base}${base.at(-1)}ed`);forms.add(`${base}${base.at(-1)}ing`)}return forms}
function phraseSearchRegularBases(token){const candidates=new Set([token]);if(token.endsWith("ies"))candidates.add(`${token.slice(0,-3)}y`);if(token.endsWith("ied"))candidates.add(`${token.slice(0,-3)}y`);if(token.endsWith("ing")){const stem=token.slice(0,-3);candidates.add(stem);candidates.add(`${stem}e`);if(stem.length>2&&stem.at(-1)===stem.at(-2))candidates.add(stem.slice(0,-1))}if(token.endsWith("ed")){const stem=token.slice(0,-2);candidates.add(stem);candidates.add(token.slice(0,-1));if(stem.length>2&&stem.at(-1)===stem.at(-2))candidates.add(stem.slice(0,-1))}if(token.endsWith("es")){candidates.add(token.slice(0,-2));candidates.add(token.slice(0,-1))}else if(token.endsWith("s"))candidates.add(token.slice(0,-1));return[...candidates].filter(base=>phraseSearchRegularForms(base).has(token))}
function phraseSearchTokenMatches(queryToken,phraseToken){if(queryToken===phraseToken)return true;const irregular=PHRASE_SEARCH_IRREGULAR_LOOKUP.get(queryToken);if(irregular)return irregular.has(phraseToken)||PHRASE_SEARCH_ALIASES.get(queryToken)?.has(phraseToken)||false;if(PHRASE_SEARCH_ALIASES.get(queryToken)?.has(phraseToken))return true;return phraseSearchRegularBases(queryToken).some(base=>phraseSearchRegularForms(base).has(phraseToken))}
function searchText(q){const n=normalize(q),queryTokens=phraseSearchTokens(q),phraseMatches=queryTokens.length?PHRASES.filter(p=>{const headingTokens=phraseSearchTokens(p.phrase);return queryTokens.every(queryToken=>headingTokens.some(phraseToken=>phraseSearchTokenMatches(queryToken,phraseToken)))}):[];return{phrases:phraseMatches.slice(0,40),phraseCount:phraseMatches.length,dialogues:DIALOGUES.filter(d=>normalize(dialogueText(d)).includes(n)).slice(0,30)}}
function openSearch(restore=false){if(document.getElementById("searchOverlay"))return;searchReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;const overlay=document.createElement("div");overlay.id="searchOverlay";overlay.className="modal-backdrop search-backdrop";overlay.onclick=event=>{if(event.target===overlay)closeSearch()};overlay.innerHTML=`<section class="modal search-modal" role="dialog" aria-modal="true" aria-labelledby="searchTitle"><div class="modal-heading"><h2 id="searchTitle">Search</h2><button class="icon-button modal-close" type="button" onclick="closeSearch()" aria-label="Close">×</button></div><input id="universalSearch" class="search-input" placeholder="Search phrases, meanings, examples, dialogues" aria-label="Universal Search"><div id="searchResults" class="search-results"><div class="empty">Search within Friends.</div></div></section>`;overlay.addEventListener("click",event=>{if(event.target.closest(".bookmark-button"))return;const card=event.target.closest(".phrase-card,.dialogue-card");if(card&&overlay.contains(card))activateCard(card)});overlay.addEventListener("keydown",event=>{const card=event.target.closest?.(".phrase-card,.dialogue-card");if(card&&(event.key==="Enter"||event.key===" ")){event.preventDefault();activateCard(card)}});document.body.appendChild(overlay);document.body.classList.add("modal-open");const input=document.getElementById("universalSearch"),results=document.getElementById("searchResults");input.value=restore?searchState.query:"";input.addEventListener("input",()=>{searchState.query=input.value;renderSearch(input.value)});if(input.value)renderSearch(input.value);if(restore)requestAnimationFrame(()=>results.scrollTo({top:searchState.scrollTop,behavior:"instant"}));input.focus({preventScroll:true})}
function closeSearch(){const overlay=document.getElementById("searchOverlay");if(!overlay)return;overlay.remove();document.body.classList.remove("modal-open");const target=searchReturnFocus;searchReturnFocus=null;if(target?.isConnected)target.focus({preventScroll:true})}
function openSearchResult(type,id){const results=document.getElementById("searchResults");searchState={query:document.getElementById("universalSearch")?.value||searchState.query,scrollTop:results?.scrollTop||0};closeSearch();if(type==="phrase"){setContinue({kind:"phrase",id});navigate("phraseDetail",{id,fromSearch:true})}else{setContinue({kind:"dialogue",id});navigate("dialogueDetail",{id,ids:searchText(searchState.query).dialogues.map(x=>x.id),fromSearch:true})}}
function renderSearch(query){const root=document.getElementById("searchResults");if(!root)return;searchState.query=query;if(!query.trim()){root.innerHTML='<div class="empty">Search within Friends.</div>';return}const result=searchText(query);root.innerHTML=`<section class="search-section"><h2 class="section-title">Phrases · ${result.phraseCount}</h2><div class="content-list phrase-grid">${result.phrases.map(p=>phraseCard(p,"openSearchPhraseResult")).join("")||'<div class="muted">No phrase matches.</div>'}</div></section><section class="search-section"><h2 class="section-title">Dialogues · ${result.dialogues.length}</h2><div class="content-list dialogue-list">${result.dialogues.map(d=>dialogueCard(d,"openSearchDialogueResult")).join("")||'<div class="muted">No dialogue matches.</div>'}</div></section>`}
function openSearchPhraseResult(id){openSearchResult("phrase",id)}
function openSearchDialogueResult(id){openSearchResult("dialogue",id)}
function showConfirm(message,action){const root=document.getElementById("modalRoot");root.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><h2>Confirm</h2><p class="muted">${esc(message)}</p><div class="button-row"><button class="secondary-button" id="cancelConfirm">Cancel</button><button class="primary-button" id="acceptConfirm">Start Over</button></div></div></div>`;document.getElementById("cancelConfirm").onclick=closeModal;document.getElementById("acceptConfirm").onclick=()=>{closeModal();action()}}

backButton.addEventListener("click",()=>route.name==="home"&&!historyStack.length?openHomeMenu():goBack());searchButton.addEventListener("click",openSearch);
desktopBackButton.addEventListener("click",goBack);
